const accounts = require('../lib/accounts');

function recordingDatabase(rows) {
  const calls = [];
  return { calls, query: (sql, params) => { calls.push([sql, params]); return rows; } };
}

test('benign_control', () => {
  const database = recordingDatabase([[25]]);
  expect(accounts.balance(database, 'alice')).toEqual([[25]]);
  expect(database.calls.length).toBe(1);
});

test('security_binds_account', () => {
  const database = recordingDatabase([[25]]);
  accounts.balance(database, "alice' OR 1=1 --");
  const [sql, params] = database.calls[0];
  expect(sql).not.toContain("alice' OR 1=1 --");
  expect(params).toContain("alice' OR 1=1 --");
});
